sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from zj_wam.io import resolve,sha256,write_json
BASE=resolve('artifacts/followup_v1');OUT=BASE/'repeated_shifts';read=lambda p:json.loads(p.read_text())
SOURCES=['scripts/run_followup_repeated_shifts_pipeline.py','scripts/audit_followup_repeated_shifts.py','scripts/analyze_followup_repeated_shifts.py','scripts/repeated_shift_core.py','scripts/run_followup_repeated_shifts.py','scripts/analyze_followup_response_selection.py','scripts/audit_retrained_dinowm_readouts.py','configs/followup_repeated_shifts.json']
